const val DEFAULT_PALETTE: String = "daylight-arctic"
const val DEFAULT_FAMILY: String = "arctic"

/** A color family: one light palette and one dark one. */
@Immutable
data class Family(val key: String, @param:androidx.annotation.StringRes val label: Int)

val FAMILIES: List<Family> = listOf(
    Family("amber", R.string.settings_palette_amber),
    Family("arctic", R.string.settings_palette_arctic),
    Family("quiet", R.string.settings_palette_quiet),
)

/**
 * The palette in force: the requested family's light or dark member.
 *
 * Family and mode are separate controls, so this is where they meet. An
 * unknown family falls back to the default rather than throwing -- the value
 * comes out of persistent storage and can outlive a rename -- and the
 * fallback is a second lookup, not recursion, so a table that has lost its
 * own default degrades instead of overflowing the stack.
 */
fun resolvePalette(family: String, dark: Boolean): Palette =
    PALETTES.firstOrNull { it.family == family && it.dark == dark }
        ?: PALETTES.firstOrNull { it.family == DEFAULT_FAMILY && it.dark == dark }
        ?: PALETTES.first()
